DO $owners$BEGIN
IF md5(pg_get_functiondef('public.fn_accounting_tournament_fee_net_plan(uuid)'::regprocedure))IS DISTINCT FROM '55d5cd47a5432866a544a455d1a774fe' THEN RAISE EXCEPTION 'feeplan_exact_owner_changed';END IF;
IF md5(pg_get_functiondef('public.fn_accounting_tournament_fee_fingerprint(public.rake_records)'::regprocedure))IS DISTINCT FROM '89523554d8b64da3e73f8d82f9f9acbd' THEN RAISE EXCEPTION 'feeplan_exact_owner_changed';END IF;
IF pg_get_indexdef('public.rake_records_tournament_small_evidence_cover'::regclass)IS DISTINCT FROM $idx$CREATE INDEX rake_records_tournament_small_evidence_cover ON public.rake_records USING btree (tournament_id, id) INCLUDE (hand_id, table_id, club_id, rake_amount, bbj_contribution, pot_size, num_players, created_at, player_contributions, global_hand_id, is_tournament, source, metadata, rake_method, returned_uncalled) WHERE (is_tournament AND (((((COALESCE(octet_length(jsonb_send(metadata)), 0))::bigint + (COALESCE(octet_length(jsonb_send(player_contributions)), 0))::bigint) + (COALESCE(octet_length(jsonb_send(returned_uncalled)), 0))::bigint) <= 448) AND ((((COALESCE(smarter_private.rake_record_jsonb_raw_size(metadata), 0))::bigint + (COALESCE(smarter_private.rake_record_jsonb_raw_size(player_contributions), 0))::bigint) + (COALESCE(smarter_private.rake_record_jsonb_raw_size(returned_uncalled), 0))::bigint) <= 1864) AND (((COALESCE(octet_length(source), 0))::bigint + (COALESCE(octet_length(rake_method), 0))::bigint) <= 128) AND ((((COALESCE(octet_length(numeric_send(rake_amount)), 0))::bigint + (COALESCE(octet_length(numeric_send(bbj_contribution)), 0))::bigint) + (COALESCE(octet_length(numeric_send(pot_size)), 0))::bigint) <= 128)))$idx$ OR NOT EXISTS(SELECT FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid WHERE i.indexrelid='public.rake_records_tournament_small_evidence_cover'::regclass AND i.indisvalid AND i.indisready AND i.indislive AND c.relowner='postgres'::regrole)THEN RAISE EXCEPTION 'feeplan_exact_existing_cover_changed';END IF;
