PREPARE feeplan_original_0(uuid)AS SELECT EXISTS(SELECT 1 FROM public.rake_records r WHERE r.tournament_id=$1 AND r.is_tournament
   AND (r.rake_amount IS NULL OR r.rake_amount<>round(r.rake_amount,2) OR r.rake_amount::text IN('NaN','Infinity','-Infinity') OR r.hand_id IS NOT NULL));
